#include "stdafx.h"#include "MnemoWnd.h"#include "PipeClient.h"#include "Function.h"#include "Lang.h"#include <assert.h>#include <tchar.h>#include "FormatScn.h"//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool ParserBuffer( CLang& def, char*& ptr, SBuffer& Buffer, SUniLogic& rLog );//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~#define DefineO  CLang& def,char* value,char*& ptr, SBuffer& Buffer, SUniLogic& rLog// 1 = Ошибка, 0 - все нормально, -1 - breaktypedef int (*LPObject)(DefineO);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int AddReturn(DefineO)  {  return -1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int AddObject(DefineO)  {//  CLang defL(def.m_queue);  if ( !ParserBuffer( def, ptr, def.m_queue.Dyna, rLog ) )    return 1;  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int AddMacros(DefineO)  {  int n = def.m_queue.cntFunc;  if ( n >= def.m_queue.maxFunc )    {    int maxPar = (def.m_queue.maxFunc+50);    SParams* arrPar = (SParams*)::BuffAlloc(maxPar*sizeof(SParams),true);    if ( arrPar == NULL )      return 1;    memcpy( arrPar, def.m_queue.arrFunc, def.m_queue.maxFunc*sizeof(SParams) );    ::BuffFree( def.m_queue.arrFunc );    def.m_queue.maxFunc = maxPar;    def.m_queue.arrFunc = arrPar;    }  //  def.m_queue.cntFunc++;  //  DWORD dwPar = def.dwPar;  for ( int i = 0; i < 10; i++, dwPar>>=1 )    {    if ( dwPar & 1 )      StrCPY( def.m_queue.arrFunc[n].szParam[i],def.szParam[i],sizeof(def.m_queue.arrFunc[n].szParam[i]));    else      StrCPY( def.m_queue.arrFunc[n].szParam[i],"0",sizeof(def.m_queue.arrFunc[n].szParam[i]));    }  //  StrCPY( def.m_queue.arrFunc[n].szName, value, sizeof(def.m_queue.arrFunc[n].szName) );  def.m_queue.arrFunc[n].buff = ptr;  while ( *ptr )    {    if ( ptr[0] == '<' )      if ( ptr[1] == '/' )        if ( tolower(ptr[2]) == 'm' )          if ( tolower(ptr[3]) == 'a' )            if ( tolower(ptr[4]) == 'c' )              if ( tolower(ptr[5]) == 'r' )                if ( tolower(ptr[6]) == 'o' )                  if ( tolower(ptr[7]) == 's' )                    if ( ptr[8] == '>' )                      {                      *ptr = '\0';                      def.m_queue.arrFunc[n].dl = lstrlen(def.m_queue.arrFunc[n].buff);                      ptr += 11;                      def.m_queue.cntFunc++;                      char* buff = (char*)::BuffAlloc( def.m_queue.arrFunc[n].dl+1, true );                      memcpy( buff, def.m_queue.arrFunc[n].buff, def.m_queue.arrFunc[n].dl );                      def.m_queue.arrFunc[n].buff = buff;                      return 0;                      }    ptr++;    }  def.m_queue.cntFunc--;  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~struct STug { char*  name;LPObject func; };static STug gs_names[] ={  {"objects",AddObject},{"/objects" ,AddReturn},  {"macros" ,AddMacros},{"/macros"  ,AddReturn},  {NULL}  };//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~SQueueTagEx GDI_Names[] =  {  #undef  QUEUE_FUNC  #define QUEUE_FUNC( Text, Func ) { Text, Func },  #include "Function.hpp"  };int GDI_Count = sizeof(GDI_Names)/sizeof(GDI_Names[0]);bool  ParserString( CLang& def, bool bStatic, SUniLogic& rLog );//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool ParserBuffer( CLang& def, char*& ptr, SBuffer& Buffer, SUniLogic& rLog )  {  static bool bInit = true;  Qsort( GDI_Names, GDI_Count, sizeof(SQueueTagEx), bInit );  //  const int nNumberOfTagsInString=50;  STegScn teg[nNumberOfTagsInString];  while ( *ptr )    {    if ( def.m_szStr[0] != 0 && def.szPtr != def.m_szStr )      ParserString( def, true, rLog );    //    def.NextTeg();    int nReturn = ParserTegEx( ptr, def.szBeg, def.szEnd, teg, nNumberOfTagsInString-1 );    //    if ( nReturn == 0 ) //Все нормально      {      if ( !def.bIf[def.nIf] )        {        if ( lstrcmpi(teg[0].name,"#if"   ) == 0 ){def.kIf++;continue;}        else        if ( lstrcmpi(teg[0].name,"#else" ) == 0 ){if ( def.kIf ) continue;}        else        if ( lstrcmpi(teg[0].name,"#endif") == 0 ){if ( def.kIf ) {def.kIf--;continue;}}        else        continue;        }      //      int n = 1;      while ( teg[n].name != NULL )        {        FindTegs(def,teg[n].name,teg[n].value);        n++;        }      //      // Ищем среди стандартных имен      if ( GDI_Names != NULL )        {        SQueueTagEx* find = (SQueueTagEx*)SearchName( teg[0].name, GDI_Names, GDI_Count, sizeof(SQueueTagEx) );        if ( find )          {//mwr-----------------------((          for(int ii=0; ii<n; ii++)           {           if( teg[ii].name != NULL )           //if( (_tcsnicmp(teg[ii].value, "$common", 7)==0) && (teg[ii].value[7] >= '0') && (teg[ii].value[7] < _countof(CLang::szCommonParam)+'0') )           if( (_tcsnicmp(teg[ii].value, "$common", 7)==0) && (teg[ii].value[7] >= '0')                && (teg[ii].value[7] < _countof(CLang::szCommonParam)+'0')                && (teg[ii].value[8] == 0)             )             teg[ii].value = CLang::szCommonParam[teg[ii].value[7]-'0'];           }//mwr-----------------------))          (*find->func)(def,teg,Buffer,rLog);          continue;          }        }      //      // Определяем имя объекта      if ( !AddObject(def,Buffer,teg[0].name,teg[0].value,rLog) )        {        nReturn = 0;        int n = 0;        while ( gs_names[n].name )          {          if ( lstrcmpi(teg[0].name,gs_names[n].name) == 0 )            {            ptr++;            nReturn = (*gs_names[n].func)(def,teg[0].value,ptr,Buffer,rLog);            break;            }          n++;          }        //        if ( nReturn == -1 )          break;        //        if ( nReturn ==  1 )          return false;        //        }      }    else    if ( nReturn == 1 ) //Конец буфера      {      return true;      }    else    if ( nReturn == -1 ) //Ошибка в формате      {      ::MessageBox( NULL, "Ошибка формата", ptr, MB_ICONSTOP );      return false;      }    }  return true;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool ParserQueue( SQueue& q, char* ptr, SUniLogic& rLog )  {  CLang def(q);  def.szPtr = ptr;  return ParserBuffer( def, ptr, def.m_queue.Stat, rLog );  }////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool ParserString( CLang& def, bool bStatic, SUniLogic& rLog )  {  char* szBeg = def.szBeg;  char* szEnd = def.szEnd;  char* old = def.szPtr;  def.szPtr = def.m_szStr;  char* ptr = def.m_szStr;  CLang::ms_nStack++;  bool bReturn;  if ( bStatic )    bReturn = ParserBuffer( def, ptr, def.m_queue.Stat, rLog );  else    bReturn = ParserBuffer( def, ptr, def.m_queue.Dyna, rLog );  CLang::ms_nStack--;  def.szPtr = old;  def.szBeg = szBeg;  def.szEnd = szEnd;  def.m_szStr[0] = 0;  return bReturn;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~